<section class="page-heading"><div><h1>Staff &amp; Permissions</h1><p>Choose what each member of your team can access.</p></div><div class="product-actions"><span class="label-chip"><?= count($staff) ?> staff accounts</span><a class="button button-primary" href="<?= e(url('/staff/form')) ?>&amp;action=create" data-staff-open="create">+ Add staff</a></div></section>
<?php if ($notice): ?><p class="notice" role="status"><?= e($notice) ?></p><?php endif; ?>
<div class="info-strip"><?= icon('info') ?><span>Manage staff logins and access for your shop. Password resets and deactivation sign out existing sessions.</span></div>
<?php if (!$staff): ?><section class="surface"><div class="empty-state"><?= icon('users') ?><h2>No staff accounts yet</h2><p>Choose Add staff to create the first account.</p></div></section><?php endif; ?>
<section class="staff-grid"><?php foreach ($staff as $member): ?><form method="post" action="<?= e(url('/staff/permissions')) ?>" class="surface staff-card" data-staff-permissions data-staff-card="<?= (int)$member['id'] ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="staff_id" value="<?= (int)$member['id'] ?>"><header><span class="avatar"><?= e(mb_strtoupper(mb_substr($member['name'],0,1))) ?></span><div><h2><?= e($member['name']) ?></h2><p><?= e($member['email']) ?></p></div><span class="label-chip"><?= $member['active']?'Active':'Inactive' ?></span></header><p class="staff-last-login">Last sign-in: <?= $member['last_login_at']?e(local_datetime($member['last_login_at'])):'Never signed in' ?></p><div class="staff-account-actions"><?php foreach(['edit'=>'Edit details','reset'=>'Reset password','status'=>$member['active']?'Deactivate':'Activate'] as $kind=>$label): ?><a class="button button-small" href="<?= e(url('/staff/form')) ?>&amp;action=<?= $kind ?>&amp;staff_id=<?= (int)$member['id'] ?>" data-staff-open="<?= $kind ?>" data-staff-id="<?= (int)$member['id'] ?>" data-staff-name="<?= e($member['name']) ?>" data-staff-email="<?= e($member['email']) ?>" data-staff-active="<?= (int)$member['active'] ?>"><?= e($label) ?></a><?php endforeach; ?></div><div class="staff-permissions-list"><?php foreach (permissions() as $key=>$label): ?><label><span><?= e($label) ?></span><input type="checkbox" name="permissions[]" value="<?= e($key) ?>" <?= in_array($key,$member['permissions'],true)?'checked':'' ?>></label><?php endforeach; ?></div><footer><span role="status" aria-live="polite"></span><button class="button button-primary" type="submit">Save permissions</button></footer></form><?php endforeach; ?></section>

<?php foreach(['create','edit','reset','status'] as $action): $values=[];$error='';$inDialog=true; ?>
<dialog class="staff-dialog" id="staff-<?= $action ?>-dialog" aria-labelledby="staff-<?= $action ?>-title"><div class="staff-dialog-heading"><h2 id="staff-<?= $action ?>-title"><?= e(['create'=>'Add staff','edit'=>'Edit staff details','reset'=>'Reset password','status'=>'Change staff status'][$action]) ?></h2><button type="button" class="icon-button" data-staff-close aria-label="Close staff dialog">×</button></div><p data-staff-subject class="subtle-text"></p><form method="post" action="<?= e(url('/staff/save')) ?>" data-staff-account><?php require __DIR__.'/staff-fields.php'; ?></form></dialog>
